bounded_host_request.command:
set -euo pipefail
image=create-videobot:local-poll
docker image inspect "$image" >/dev/null 2>&1 || exit 61
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || exit 62
pg_ip="$(docker inspect -f '{{with index .NetworkSettings.Networks "deploy_default"}}{{.IPAddress}}{{end}}' "$pg")"
echo "$pg_ip" | grep -Eq '^(10|172|192)\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$' || exit 63
docker run --rm --network host --pull never --read-only --cap-drop ALL \
 --security-opt no-new-privileges:true --entrypoint node "$image" -e '
const timer=AbortSignal.timeout(11000);
try {
 const res=await fetch("https://api.telegram.org",{signal:timer});
 if(res.status<500)process.exitCode=0;
 else process.exitCode=80;
} catch {process.exitCode=80;}
' || { echo STK04_HOST_NET_TELEGRAM_FAIL; exit 80; }
docker run --rm --network host --pull never --read-only --cap-drop ALL \
 --security-opt no-new-privileges:true -e "STK04_PG_IP=$pg_ip" --entrypoint node "$image" -e '
const net=require("node:net");
const host=process.env.STK04_PG_IP;
const s=net.connect({host,port:5432});
let done=false;
const finish=ok=>{if(done)return;done=true;s.destroy();process.exitCode=ok?0:81};
s.once("connect",()=>finish(true));
s.once("error",()=>finish(false));
s.setTimeout(6000,()=>finish(false));
' || { echo STK04_HOST_NET_POSTGRES_TCP_FAIL; exit 81; }
echo STK04_HOST_NET_TELEGRAM_AND_PG_TCP=PASS
